import{_ as o,a0 as l,w as d,s as r,ao as n,I as s,a1 as p,A as e,x as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const c=JSON.parse('{"title":"使用 Pip 升級 Python 軟件包 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Pip 升級 Python 軟件包 | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Pip 升級 Python 軟件包 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Pip 升級 Python 軟件包 | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20221027.0 ⭐️ How to Upgrade Python Packages with Pip","title":"使用 Pip 升級 Python 軟件包","tag":"202211","desc":""},"relativePath":"202211/20221027.0 ⭐️ How to Upgrade Python Packages with Pip.md","filePath":"[post].md"}'),h={name:"202211/20221027.0 ⭐️ How to Upgrade Python Packages with Pip.md"};function g(u,t,k,b,P,f){const a=l("Link");return d(),r("div",null,[t[26]||(t[26]=n('<h1 id="使用-pip-升級-python-軟件包" tabindex="-1">使用 Pip 升級 Python 軟件包 <a class="header-anchor" href="#使用-pip-升級-python-軟件包" aria-label="Permalink to “使用 Pip 升級 Python 軟件包”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202211/07/153408lqflbw3mwxja3qm4.jpg" alt=""></p><p>你上次更新通過 Pip 安裝的 Python 軟件包是什麼時候？大多數用户往往會忘記這些 Python 軟件包也需要手動更新，因為僅僅更新系統存儲庫對於軟件包來説是不起作用的。</p><p>因此，讓我們花點時間看看如何使用 Pip，來更新舊的 Python 軟件包吧。</p><h3 id="如何使用-pip-升級-python-軟件包" tabindex="-1">如何使用 Pip 升級 Python 軟件包 <a class="header-anchor" href="#如何使用-pip-升級-python-軟件包" aria-label="Permalink to “如何使用 Pip 升級 Python 軟件包”">​</a></h3>',5)),s("p",null,[p(a,{href:"https://itsfoss.com/install-pip-ubuntu/"},{default:e(()=>[...t[0]||(t[0]=[i("Pip（Pip Installs Packages）",-1)])]),_:1}),t[1]||(t[1]=i(" 是一個用於管理 Python 軟件包的 ",-1)),t[2]||(t[2]=s("ruby",null,[i("命令列實用程序 "),s("rt",null," command line utility ")],-1)),t[3]||(t[3]=i(" 。你可以將 Pip 安裝 Python 軟件包，類比為在 Ubuntu 和 Debian 中使用 ",-1)),t[4]||(t[4]=s("code",null,"apt",-1)),t[5]||(t[5]=i(" 管理軟件包那樣。",-1))]),t[27]||(t[27]=n('<p>因此，接下來就讓我們深入瞭解如何使用這個極好的工具 Pip，來管理與 Python 軟件包相關的內容吧。</p><h4 id="_1、列出過時的-python-軟件包" tabindex="-1">1、列出過時的 Python 軟件包 <a class="header-anchor" href="#_1、列出過時的-python-軟件包" aria-label="Permalink to “1、列出過時的 Python 軟件包”">​</a></h4><p>在計劃更新什麼軟件包之前，我們先要列出有哪些過時的軟件包，你可以在其中選擇想要更新的軟件包，因為大多數人不會想一下子更新整個軟件包庫。</p><p>要列出過時的 Python 軟件包，你只需將 <code>pip</code> 命令與 <code>list</code> 選項、<code>--outdated</code> 標誌一同使用即可，如下圖所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pip list --outdated</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/09/outdated-packages.png" alt="outdated packages"></p><h4 id="_2、升級特定的軟件包" tabindex="-1">2、升級特定的軟件包 <a class="header-anchor" href="#_2、升級特定的軟件包" aria-label="Permalink to “2、升級特定的軟件包”">​</a></h4><p>獲得可更新的軟件包列表後，你可以像我之前提到的那樣，選擇你要更新的那個特定的軟件包，pip 升級軟件包命令的語法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pip install package_name -U</span></span></code></pre></div><p>例如，我想將名為 <code>anime-api</code> 的軟件包升級到最新版本，所以我將使用下面的命令來升級：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pip install anime-api -U</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/09/update-anime-api.png" alt="update anime api"></p><h4 id="_3、將軟件包升級到特定的版本" tabindex="-1">3、將軟件包升級到特定的版本 <a class="header-anchor" href="#_3、將軟件包升級到特定的版本" aria-label="Permalink to “3、將軟件包升級到特定的版本”">​</a></h4><p>沒有必要總是使用軟件的最新版本，如果你想將軟件包升級到不是最新的某個特定版本，參考如下的命令語法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pip install --upgrade &lt;package&gt;==&lt;version&gt;</span></span></code></pre></div><p>例如，我想將名為 <code>xdg</code> 的軟件包更新到 5.1 版本，5.1 版本是最新版本的前一個版本，所以可以使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pip install --upgrade xdg==5.1</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/09/upgrade-xdg-to-specific-iteration.png" alt="upgrade xdg to specific iteration"></p><h4 id="_4、使用-pip-一次性升級所有軟件包" tabindex="-1">4、使用 Pip 一次性升級所有軟件包 <a class="header-anchor" href="#_4、使用-pip-一次性升級所有軟件包" aria-label="Permalink to “4、使用 Pip 一次性升級所有軟件包”">​</a></h4><p><strong>請注意：我不建議你一次性升級所以軟件包，因為 Python 軟件包的依賴項太複雜了，一次性的升級無法處理相互依賴項。</strong></p><p>要一次性升級所有 python 軟件包，你可以使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pip3 list --outdated --format=freeze | grep -v &#39;^\\-e&#39; | cut -d = -f 1 | xargs -n1 pip3 install -U</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/09/upgrade-everything.png" alt="upgrade everything"></p>',23)),s("p",null,[t[7]||(t[7]=i("上面的命令使用了 ",-1)),p(a,{href:"https://linuxhandbook.com/xargs-command/"},{default:e(()=>[...t[6]||(t[6]=[i("xargs",-1)])]),_:1}),t[8]||(t[8]=i("。首先，會得到所有需要更新的軟件包，然後對每個軟件包執行 ",-1)),t[9]||(t[9]=s("code",null,"pip3 install -U",-1)),t[10]||(t[10]=i(" 命令。",-1))]),t[28]||(t[28]=n('<p>我在這裏使用的是 <code>pip3</code>，而不是 <code>pip</code>。在 Ubuntu 22.04 及更高的版本中，<code>pip</code> 和 <code>pip3</code> 命令都可以使用。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>使用 Pip 一次性更新所有 Python 軟件包並不是一個好主意。我發現一次性更新後，軟件包之間的依賴關係被破壞了，所以請確保只更新你想要更新的軟件包。</p><p>如果你還有其他的疑問，就請在評論區中留言吧。</p><hr>',5)),s("p",null,[t[12]||(t[12]=i("via: ",-1)),p(a,{href:"https://itsfoss.com/upgrade-pip-packages/"},{default:e(()=>[...t[11]||(t[11]=[i("https://itsfoss.com/upgrade-pip-packages/",-1)])]),_:1})]),s("p",null,[t[17]||(t[17]=i("作者：",-1)),p(a,{href:"https://itsfoss.com/author/sagar/"},{default:e(()=>[...t[13]||(t[13]=[i("Sagar Sharma",-1)])]),_:1}),t[18]||(t[18]=i(" 選題：",-1)),p(a,{href:"https://github.com/lkxed"},{default:e(()=>[...t[14]||(t[14]=[i("lkxed",-1)])]),_:1}),t[19]||(t[19]=i(" 譯者：",-1)),p(a,{href:"https://github.com/chai001125"},{default:e(()=>[...t[15]||(t[15]=[i("chai001125",-1)])]),_:1}),t[20]||(t[20]=i(" 校對：",-1)),p(a,{href:"https://github.com/wxy"},{default:e(()=>[...t[16]||(t[16]=[i("wxy",-1)])]),_:1})]),s("p",null,[t[23]||(t[23]=i("本文由 ",-1)),p(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[21]||(t[21]=[i("LCTT",-1)])]),_:1}),t[24]||(t[24]=i(" 原創編譯，",-1)),p(a,{href:"https://linux.cn/"},{default:e(()=>[...t[22]||(t[22]=[i("Linux中國",-1)])]),_:1}),t[25]||(t[25]=i(" 榮譽推出",-1))])])}const x=o(h,[["render",g]]);export{c as __pageData,x as default};
